<script lang="ts">
 import SquareTerminal from '@lucide/svelte/icons/square-terminal';import ScanSearch from '@lucide/svelte/icons/scan-search';import Search from '@lucide/svelte/icons/search';import Keyboard from '@lucide/svelte/icons/keyboard';import type {WorkbenchState} from '../lib/workbench-state.js';export let state:WorkbenchState;void state;let open='';
 const menuEntries:[string,any[]][]=[['File',[['Open file','atlas:focus-files'],['Close panel','atlas:close-panel']]],['Edit',[['Find','atlas:search'],['Save file','atlas:save-file']]],['Selection',[['Focus context','atlas:focus-context']]],['Find',[['Search files and symbols','atlas:focus-search']]],['View',[['Toggle terminal','atlas:open-terminal'],['Focus filesystem','atlas:focus-files']]],['Tools',[['Scan selected host','atlas:scan'],['Map repository','atlas:analyze']]],['Help',[['Keyboard shortcuts','atlas:shortcuts']]]];
